# Arsenal shell integration (generated by "ars hook")
ars() {
  local _cdf _cmdf _rc _d _c
  if [ "${1:-}" = pause ] && [ $# -eq 1 ]; then
    if [ -z "${ARSENAL_PAUSED:-}" ]; then
      [ -n "${ARSENAL_REC:-}" ] && printf '\033]7777;ars;pause;\007' > /dev/tty 2>/dev/null
      export ARSENAL_PAUSED=1
      printf 'Paused: commands are not logged%s in this terminal. Run ars pause again to resume.\n' "${ARSENAL_REC:+ and the recording is paused}" >&2
    else
      unset ARSENAL_PAUSED
      [ -n "${ARSENAL_REC:-}" ] && printf '\033]7777;ars;resume;\007' > /dev/tty 2>/dev/null
      printf 'Resumed: commands are logged%s in this terminal.\n' "${ARSENAL_REC:+ and recorded}" >&2
    fi
    return 0
  fi
  _cdf="$(mktemp "${TMPDIR:-/tmp}/ars-cd.XXXXXX")" || { command ars "$@"; return $?; }
  _cmdf="$(mktemp "${TMPDIR:-/tmp}/ars-cmd.XXXXXX")" || { rm -f "$_cdf"; command ars "$@"; return $?; }
  ARSENAL_CD_FILE="$_cdf" ARSENAL_CMD_FILE="$_cmdf" command ars "$@"
  _rc=$?
  if [ -s "$_cdf" ]; then
    _d="$(cat "$_cdf")"
    if [ -d "$_d" ]; then
      cd -- "$_d"
    fi
  fi
  if [ -s "$_cmdf" ]; then
    _c="$(cat "$_cmdf")"
    if [ -n "${ZSH_VERSION:-}" ]; then
      print -z -- "$_c"
    elif [ -n "${BASH_VERSION:-}" ]; then
      history -s -- "$_c"
      printf '%s\n' "Command added to your history: press the up arrow to use it" >&2
    fi
  fi
  rm -f "$_cdf" "$_cmdf"
  return $_rc
}
arsenal() { ars "$@"; }
